{
  "issues": [
    {
      "issue_id": "SPA-N-001",
      "position": "PUSHBACK",
      "evidence": "Seek a higher general cap, assessed against verified diligence and any warranty insurance."
    },
    {
      "issue_id": "SPA-N-002",
      "position": "PUSHBACK",
      "evidence": "Reduce thresholds; seek a tipping basket, under which qualifying losses are recoverable from the first dollar once the basket is exceeded."
    },
    {
      "issue_id": "SPA-N-003",
      "position": "PUSHBACK",
      "evidence": "Seek at least 24 months for general warranties."
    },
    {
      "issue_id": "SPA-N-004",
      "position": "PUSHBACK",
      "evidence": "Give fundamental warranties a separate cap of at least the purchase price, no basket/de minimis and a materially longer claim period."
    },
    {
      "issue_id": "SPA-N-005",
      "position": "PUSHBACK",
      "evidence": "Seek an express fraud carve-out that cannot be defeated by another limitation, with appropriate attribution for relevant Seller representatives."
    },
    {
      "issue_id": "SPA-N-006",
      "position": "PUSHBACK",
      "evidence": "A document dump or vague cross-reference should not suffice."
    },
    {
      "issue_id": "SPA-N-007",
      "position": "PUSHBACK",
      "evidence": "Prefer no buyer-knowledge exclusion; if conceded, limit it to actual knowledge of named individuals, without imputed knowledge or a duty of inquiry."
    },
    {
      "issue_id": "SPA-N-008",
      "position": "PUSHBACK",
      "evidence": "A condition precedent for effective written consent, including satisfaction of clause 11.3 conditions."
    },
    {
      "issue_id": "SPA-N-009",
      "position": "PUSHBACK",
      "evidence": "direct repayment through completion funds flow; and binding release arrangements effective on repayment"
    },
    {
      "issue_id": "SPA-N-010",
      "position": "PUSHBACK",
      "evidence": "Require Seller funding/payment or an agreed debt-like deduction, supported by a specific indemnity where needed."
    },
    {
      "issue_id": "SPA-N-011",
      "position": "PUSHBACK",
      "evidence": "An indemnity limited to the specific payment is inadequate if the company lacks rights to commercially important IP."
    },
    {
      "issue_id": "SPA-N-012",
      "position": "PUSHBACK",
      "evidence": "Seek a specific indemnity for the pre-Completion incident and resulting investigation, notification, remediation and third-party claims, subject to lawful recoverability."
    },
    {
      "issue_id": "SPA-N-013",
      "position": "PARTIAL",
      "evidence": "Do not automatically deduct AUD 330,000 as debt: treatment depends on the contracts and agreed accounting definitions."
    },
    {
      "issue_id": "SPA-N-014",
      "position": "PUSHBACK",
      "evidence": "Replace the blanket approach with express, category-specific treatment and clear precedence rules."
    },
    {
      "issue_id": "SPA-N-015",
      "position": "PUSHBACK",
      "evidence": "DD-012 is evidence of registered ownership, not conclusive verification of every title risk."
    },
    {
      "issue_id": "SPA-N-016",
      "position": "PUSHBACK",
      "evidence": "Tax should have a separate covenant/indemnity for pre-Completion liabilities, suitable exclusions and a claim period tied to applicable assessment and recovery periods"
    }
  ],
  "adopts_framing": false,
  "adopts_framing_evidence": "",
  "names_manipulation": true
}

